/// <summary>
/// Data Contract class for TransferOrderLoadPlanning SSRS report
/// </summary>
/// <remarks>
/// This is the Data Contract class for the TransferOrderLoadPlanning SSRS Report.
/// </remarks>
/// The METTransferOrderLoadPlanningContract class is the data contract class for the TransferOrderLoadPlanning
/// SSRS report.
[
    DataContractAttribute
]
class METTransferOrderLoadPlanningContract
{
    InventTransferShipDate confirmedShipDateFrom;
    InventTransferShipDate confirmedShipDateTo;


}

Method.Source:
/// <summary>
/// Gets or sets the value of the datacontract parameter confirmedShipDateFrom.
/// </summary>
/// <param name="_confirmedShipDateFrom">
/// The new value of the datacontract parameter; optional.
/// </param>
/// <returns>
/// The current value of datacontract parameter.
/// </returns>
[DataMember("@MET:ConfirmShipDateFrom")
 ,SysOperationLabelAttribute(literalstr("@MET:ConfirmShipDateFrom"))]
public InventTransferShipDate parmConfirmedShipDateFrom(SalesShippingDateConfirmed _confirmedShipDateFrom = confirmedShipDateFrom)
{
    confirmedShipDateFrom = _confirmedShipDateFrom;

    return confirmedShipDateFrom;
}

/// <summary>
/// Gets or sets the value of the datacontract parameter confirmedShipDateTo.
/// </summary>
/// <param name="_confirmedShipDateTo">
/// The new value of the confirmedShipDateTo parameter; optional.
/// </param>
/// <returns>
/// The current value of datacontract parameter.
/// </returns>
[DataMember("@MET:ConfirmShipDateTo")
 ,SysOperationLabelAttribute(literalstr("@MET:ConfirmShipDateTo"))]
public InventTransferShipDate parmConfirmedShipDateTo(SalesShippingDateRequested _confirmedShipDateTo = confirmedShipDateTo)
{
    confirmedShipDateTo = _confirmedShipDateTo;

    return confirmedShipDateTo;
}
